use serde::{Deserialize, Serialize};
use std::collections::HashMap;

impl Crate { pub fn base (self) -> base_db :: Crate { self . id } pub fn origin (self , db : & dyn HirDatabase) -> CrateOrigin { self . id . data (db) . origin . clone () } pub fn is_builtin (self , db : & dyn HirDatabase) -> bool { matches ! (self . origin (db) , CrateOrigin :: Lang (_)) } pub fn dependencies (self , db : & dyn HirDatabase) -> Vec < CrateDependency > { self . id . data (db) . dependencies . iter () . map (| dep | { let krate = Crate { id : dep . crate_id } ; let name = dep . as_name () ; CrateDependency { krate , name } }) . collect () } pub fn reverse_dependencies (self , db : & dyn HirDatabase) -> Vec < Crate > { let all_crates = db . all_crates () ; all_crates . iter () . copied () . filter (| & krate | { krate . data (db) . dependencies . iter () . any (| it | it . crate_id == self . id) }) . map (| id | Crate { id }) . collect () } pub fn transitive_reverse_dependencies (self , db : & dyn HirDatabase ,) -> impl Iterator < Item = Crate > { self . id . transitive_rev_deps (db) . into_iter () . map (| id | Crate { id }) } pub fn notable_traits_in_deps (self , db : & dyn HirDatabase) -> impl Iterator < Item = & TraitId > { self . id . transitive_deps (db) . into_iter () . filter_map (| krate | db . crate_notable_traits (krate)) . flatten () } pub fn root_module (self) -> Module { Module { id : CrateRootModuleId :: from (self . id) . into () , } } pub fn modules (self , db : & dyn HirDatabase) -> Vec < Module > { let def_map = crate_def_map (db , self . id) ; def_map . modules () . map (| (id , _) | def_map . module_id (id) . into ()) . collect () } pub fn root_file (self , db : & dyn HirDatabase) -> FileId { self . id . data (db) . root_file_id } pub fn edition (self , db : & dyn HirDatabase) -> Edition { self . id . data (db) . edition } pub fn version (self , db : & dyn HirDatabase) -> Option < String > { self . id . extra_data (db) . version . clone () } pub fn display_name (self , db : & dyn HirDatabase) -> Option < CrateDisplayName > { self . id . extra_data (db) . display_name . clone () } pub fn query_external_importables (self , db : & dyn DefDatabase , query : import_map :: Query ,) -> impl Iterator < Item = (Either < ModuleDef , Macro > , Complete) > { let _p = tracing :: info_span ! ("query_external_importables") . entered () ; import_map :: search_dependencies (db , self . into () , & query) . into_iter () . map (| (item , do_not_complete) | { let item = match ItemInNs :: from (item) { ItemInNs :: Types (mod_id) | ItemInNs :: Values (mod_id) => Either :: Left (mod_id) , ItemInNs :: Macros (mac_id) => Either :: Right (mac_id) , } ; (item , do_not_complete) }) } pub fn all (db : & dyn HirDatabase) -> Vec < Crate > { db . all_crates () . iter () . map (| & id | Crate { id }) . collect () } # [doc = " Try to get the root URL of the documentation of a crate."] pub fn get_html_root_url (self : & Crate , db : & dyn HirDatabase) -> Option < String > { let attrs = db . attrs (AttrDefId :: ModuleId (self . root_module () . into ())) ; let doc_url = attrs . by_key (sym :: doc) . find_string_value_in_tt (sym :: html_root_url) ; doc_url . map (| s | s . trim_matches ('"') . trim_end_matches ('/') . to_owned () + "/") } pub fn cfg < 'db > (& self , db : & 'db dyn HirDatabase) -> & 'db CfgOptions { self . id . cfg_options (db) } pub fn potential_cfg < 'db > (& self , db : & 'db dyn HirDatabase) -> & 'db CfgOptions { let data = self . id . extra_data (db) ; data . potential_cfg_options . as_ref () . unwrap_or_else (| | self . id . cfg_options (db)) } pub fn to_display_target (self , db : & dyn HirDatabase) -> DisplayTarget { DisplayTarget :: from_crate (db , self . id) } fn core (db : & dyn HirDatabase) -> Option < Crate > { db . all_crates () . iter () . copied () . find (| & krate | { matches ! (krate . data (db) . origin , CrateOrigin :: Lang (LangCrateOrigin :: Core)) }) . map (Crate :: from) } }